-- Popravka 6 dugih tumacenja u koja je procurio sirovi Word XML.
-- Uzrok je bio regex u scripts/korpus/parse_docx.py: <w:t[^>]*> je hvatao i
-- <w:tab w:val="clear"/>, pa je ceo <w:pPr> blok zavrsio kao tekst.
-- Parser je popravljen; ovo prepisuje zapise koji su vec u bazi.

update public.transit_texts set
  title    = $tx$Kreativna inspiracija i duhovni rast$tx$,
  body     = $tx$Snovi i akcija se sada ne isključuju – naprotiv, savršeno se nadopunjuju. Ovaj aspekt vam donosi inspiraciju i motivaciju da krenete za onim što vam je duhovno važno. Imate mogućnost da delujete saosećajno, intuitivno, ali i fokusirano, što je retka kombinacija. Mars trigon Neptun vas poziva da radite za nešto veće od sebe – umetnost, duhovnost, humanitarni rad.

Povezanost sa intuicijom i maštom sada je na vrhuncu, otvarajući vrata za duboko umetničko stvaranje i duhovne aktivnosti, kao što su meditacija i istraživanje unutrašnjih svetova. Idealno je vreme za umetničke projekte, kao i za duhovne aktivnosti, kao što su meditacija i duhovna istraživanja. Vaša sposobnost da se povežete sa svojim unutrašnjim svetom je na vrhuncu, što vam omogućava da iskoristite svoju kreativnost u svim oblastima života.

Osećate poriv da pretvorite inspiraciju u stvarnost. Imate snagu da se pokrenete u pravcu vizije, ali bez potrebe za borbom ili dokazivanjem. Ako slušate svoju intuiciju, sada možete učiniti konkretne korake koji vas vode ka ispunjenju duše. Ovo je vreme za stvaranje iz ideala – bez gubitka u iluziji.$tx$,
  sections = $tx$[{"heading": "Pozitivni efekti:", "body": "Intuicija i mašta – Kreativne ideje dolaze lako, kao i sposobnost da povežete ideje.Duhovni rast – Jača vaša sposobnost da se povezujete sa višim nivoima svesti.Saosećanje – Pojačana želja da pomognete drugima i doprinosite zajednici."}, {"heading": "Izazovi:", "body": "Idealizacija – Možete imati prevelika očekivanja, što može dovesti do razočaranja.Zbunjenost – Ponekad ćete biti nesigurni u svoje odluke zbog previše emocionalnog angažovanja.Bežanje od stvarnosti – Potreba za idealnim svetom može vas udaljiti od stvarnih problema."}, {"heading": "Saveti:", "body": "Povedite računa o stvarnosti – Ostanite realni, iako vas mašta povlači.Uživajte u tišini – Iskoristite meditaciju i tišinu da se povežete sa sobom.Pomozite drugima – Angažujte se u volonterskim i humanitarnim aktivnostima."}]$tx$
where key = 'transit.mars.trine.natal.neptune' and version = 'long';

update public.transit_texts set
  title    = $tx$Testovi u ljubavi, prijateljstvu i finansijama$tx$,
  body     = $tx$Negativni tranziti Saturna prema Veneri ukazuju na težak period u svim vrstama veza — bilo da su emotivne, poslovne ili prijateljske prirode. Ovo je vreme testova, borbe i suđenja u kojima se jasno ističe šta u vašem životu ima stabilne temelje, a šta ne. Možete osećati da više ne privlačite ljude i stvari koje ste ranije lako imali, što dovodi do pojačane sumnjičavosti i emotivne rezervisanosti. Potrebno vam je vreme da razjasnite koga zaista želite i šta vam je u ovom trenutku potrebno. Ukoliko se osećate nesposobnim da nastavite sa trenutnim odnosima ili finansijskim situacijama, savetuje se strpljenje i čekanje na kraj tranzita pre donošenja važnih odluka.

Tokom ovog perioda često dolazi do suočavanja sa zabludama koje ste možda imali oko partnerstava, druženja i finansija. Iako vam može delovati da površinske veze gube smisao i izazivaju prezir, istovremeno se otvaraju mogućnosti za stvaranje dubljih i kvalitetnijih odnosa. Relacije zasnovane na slabim temeljima gotovo sigurno neće izdržati, ali one koje su iskrene i postojane mogu ojačati i postati značajno stabilnije. Nedostatak seksualne želje i energetska iscrpljenost su česti prateći simptomi ovog tranzita, kao i problemi sa finansijama. Takođe, moguće su i gubitke ličnih vrednih stvari, što dodatno pojačava osećaj nesigurnosti.$tx$,
  sections = $tx$[{"heading": "Dugoročni efekti", "body": "Saturnova opozicija Venere donosi duboke transformacije u vašem odnosu prema ljubavi, vrednostima i sopstvenom samopoštovanju. Dugoročno, ovaj tranzit vas uči kako da cenite stabilnost i kvalitet u vezama, a ne površnost i privid. Kroz suočavanje sa gubicima i emotivnim iskušenjima, razvijate zreliji pristup odnosima i novčanim pitanjima. Može doći do trajnog pomaka u vašem sistemu vrednosti, gde se fokus premešta sa spoljašnjeg zadovoljstva na unutrašnju sigurnost i odgovornost. Ovaj proces je često bolan, ali vam pomaže da izgradite autentičniju i stabilniju osnovu za budućnost.\n\nU sferi finansija i ličnih vrednosti, tranzit može označiti kraj jednog perioda trošenja i nepromišljenih investicija, ali i početak ozbiljnijeg planiranja i štednje. Naučićete kako da prepoznate šta vam je zaista važno i koje odnose treba negovati, a koje otpustiti. Takođe, ovaj tranzit može probuditi vašu sposobnost za dugoročnu predanost i upornost, bilo u ljubavi ili poslovnom životu. Iako je period izazovan, rezultati će biti vredni uloženog truda."}, {"heading": "Specifične sfere života", "body": "• Ljubavni odnosi: testiranje snage i postojanosti partnerstava, mogućnost raskida ili produbljivanja veze\n\n• Prijateljstva i društvene veze: selekcija iskrenih prijatelja i odbacivanje površnih kontakata\n\n• Finansije i vrednosti: suočavanje sa ograničenjima, potreba za boljim finansijskim planiranjem\n\n• Samopoštovanje i lične vrednosti: redefinisanje sopstvene vrednosti nezavisno od spoljašnjih faktora\n\n• Seksualnost i intimnost: mogući problemi sa željom i emocionalnom povezanošću"}, {"heading": "Opšte preporuke", "body": "• Ne žurite sa odlukama – Emotivne i finansijske odluke najbolje je donositi nakon što tranzit prođe.\n\n• Radite na sebi – Iskoristite period za jačanje samopoštovanja i unutrašnje stabilnosti.\n\n• Komunicirajte iskreno – Otvoreni razgovori sa partnerima i bliskim osobama mogu otkloniti mnoge nesporazume.\n\n• Pazite na finansije – Izbegavajte rizične investicije i nepotrebne troškove.\n\n• Prihvatite lekcije – Razumevanje šta vam odnosi i finansije stvarno znače može biti bolno, ali je ključno za vaš razvoj."}, {"heading": "Pozitivni efekti", "body": "• Jasnije granice u odnosima – Učite da postavite granice koje štite vašu emocionalnu stabilnost.\n\n• Realniji pogled na ljubav i novac – Odbacujete iluzije i usmeravate se na ono što je stvarno.\n\n• Jačanje samopoštovanja – Izazovi vas motivišu da radite na unutrašnjoj snazi i sigurnosti.\n\n• Očvršćivanje odnosa – Stabilne veze dobijaju novu dimenziju poverenja i zrelosti.\n\n• Povećana odgovornost – Postajete zreliji u finansijskim i emotivnim obavezama."}, {"heading": "Izazovi", "body": "• Emotivna distanca i hladnoća – Moguća osećanja izolacije i otuđenosti u bliskim odnosima.\n\n• Sumnjičavost i nesigurnost – Teškoće u poverenju prema partnerima i prijateljima.\n\n• Finansijske blokade – Problemi sa novcem mogu pojačati stres i zabrinutost.\n\n• Nedostatak seksualne želje – Pad intime i povezanosti sa partnerom.\n\n• Gubici i razočarenja – Mogući emotivni ili materijalni gubici."}, {"heading": "Saveti", "body": "Budite strpljivi i pratite tok događaja – Ne forsirajte promene, dozvolite da se stvari razvijaju prirodno.\n\nRadite na unutrašnjoj snazi – Meditacija, hobiji i samorefleksija mogu vam pomoći da se osećate stabilnije.\n\nOtvoreno razgovarajte sa partnerima – Izbegavajte skrivene tenzije i neizrečene reči.\n\nPlanirajte finansije pažljivo – Budite konzervativni i racionalni u novčanim odlukama.\n\nPrihvatite transformaciju – Gubitke gledajte kao priliku za novi početak i lični rast."}]$tx$
where key = 'transit.saturn.opposition.natal.venus' and version = 'long';

update public.transit_texts set
  title    = $tx$Izgradnja discipline i kontrolisana energija$tx$,
  body     = $tx$Pri pozitivnim tranzitima kao što je sekstil između Saturna i Marsa imate sposobnost da uravnotežite energetski nivo, volju da disciplinujete sebe i strpljenje da održite progres. Ako je Mars Vaša lična planeta, Saturn u tom slučaju ima mirniji efekat, a ako je Saturn dominantnija planeta u natalu, energija je podstaknuta. Ako imate bilo kakvih poteškoća u ovom periodu, planete vas podržavaju da se izborite sa njima. Više ste u kontaktu sa vašim telom, u smislu fizičkih vežbi tokom ovih tranzita; ovo je, uzgred, jedan od najboljih aspekata za početak rutinskih vežbi, drugi je Saturn trigon Ascendent.

Samodisciplina i motivacija su neophodne za hlađenje strasti i povećanje fokusa u radu i aktivnostima. Sada osećate da kontrolišete strasti i impulse, praktičniji ste nego što je uobičajeno, a vaš napredak u većini projekata je možda spor, ali stabilan. Ovo je veoma produktivno vreme u vašem životu. Postoje razlike koje treba imati na umu između pozitivnih tranzita; kod trigona promene su prirodne i spontane, dok sekstil predstavlja mogućnost koju treba da uhvatite.$tx$,
  sections = $tx$[{"heading": "Dugoročni efekti", "body": "Ovaj tranzit postavlja čvrste temelje za vašu sposobnost samodiscipline i samokontrole, što će vam služiti tokom celog života. Razvijate trajnu otpornost na stres i prepreke, čime povećavate svoju efikasnost u različitim životnim oblastima. Naučeni ste kako da usmerite svoju energiju na konstruktivan i produktivan način, čime se smanjuju sukobi i impulzivne reakcije. Dugoročno, vaša sposobnost da balansirate ambiciju i realnost vodi ka stabilnijem i uspešnijem životu, bilo da je reč o karijeri ili ličnim ciljevima. Ovaj aspekt podstiče trajnu posvećenost zdravlju i dobrobiti, kroz usvajanje zdravih navika koje vam pomažu da održite vitalnost."}, {"heading": "Specifične sfere života", "body": "• Fizičko zdravlje i energija: Povećana sposobnost za redovne vežbe i zdrav životni stil, što doprinosi ukupnom osećaju vitalnosti.\n\n• Karijera i profesionalni razvoj: Strpljiv i dosledan rad donosi priznanje i napredovanje, otvarajući vrata novim mogućnostima.\n\n• Lični razvoj: Jačanje discipline i samokontrole u svakodnevnim aktivnostima pomaže vam da ostvarite svoje dugoročne ciljeve.\n\n• Međuljudski odnosi: Bolja kontrola impulsa i uspostavljanje stabilnijih odnosa olakšavaju komunikaciju i saradnju.\n\n• Mentalna snaga: Povećanje otpornosti na stres i prepreke omogućava vam da ostanete fokusirani i motivisani čak i u teškim situacijama."}, {"heading": "Opšte preporuke", "body": "• Iskoristite prilike za dugoročni rad – Fokusirajte se na ciljeve koji zahtevaju upornost i disciplinu, jer sada imate snagu za njihovu realizaciju.\n\nUključite fizičku aktivnost u rutinu – Vežbanje će podržati vašu energiju i mentalnu jasnoću, a takođe će vam pomoći da se oslobodite napetosti.\n\n• Radite na samokontroli – Ovaj period je idealan za smanjenje impulzivnosti i donošenje promišljenih odluka koje vode do stabilnosti.\n\n• Budite strpljivi sa napretkom – Stabilan, spor korak vodi do trajnih rezultata, zato ne odustajte zbog trenutnih prepreka.\n\n• Postavljajte realne ciljeve – Fokusirajte se na ono što možete da kontrolišete i izgradite temelje za budućnost sa poverenjem."}, {"heading": "Pozitivni efekti", "body": "• Povećana disciplina i samokontrola – Lakše upravljate energijom i impulsima, što doprinosi uspešnijem ostvarivanju ciljeva.\n\n• Stabilan i postojan napredak – Rezultati se ostvaruju kroz uporan rad i doslednost, što donosi osećaj sigurnosti.\n\n• Bolje zdravlje i vitalnost – Fizička aktivnost i rutina donose dugoročne benefite za telo i um.\n\n• Veća otpornost na stres – Sposobnost da hladnokrvno rešavate izazove smanjuje anksioznost i povećava samopouzdanje.\n\n• Jačanje samopouzdanja – Uspeh u kontroli strasti i rada gradi unutrašnju snagu i motivaciju za dalje korake."}, {"heading": "Izazovi", "body": "• Sklonost ka tvrdoglavosti – Može se javiti otpor prema promenama, što može otežati prilagođavanje novim okolnostima.\n\n• Mogućnost prenaprezanja – Prevelika ambicija može dovesti do iscrpljenosti ako ne vodite računa o odmoru.\n\n• Povremena frustracija zbog sporog napretka – Potrebno je održati fokus i strpljenje kako ne biste odustali prerano.\n\n• Teškoće u balansiranju rada i odmora – Važno je prepoznati svoje granice i praviti potrebne pauze.\n\n• Kontrola impulsa može zahtevati dodatni napor – Posebno ako ste skloni brzopletim reakcijama, važno je raditi na emocionalnoj disciplini."}, {"heading": "Saveti", "body": "• Planirajte svoje aktivnosti pažljivo – Dajte prioritet zadacima koji donose dugoročne rezultate i izbegavajte nepotrebne distrakcije.\n\n• Uključite redovne fizičke vežbe – To će vam pomoći da održite energiju i fokus, kao i da smanjite napetost.\n\n• Praktikujte strpljenje i istrajnost – Ne odustajte zbog privremenih prepreka i učite iz svakog koraka napred.\n\n• Radite na emocionalnoj samokontroli – Tehnike disanja, meditacija i samorefleksija mogu vam pomoći da ostanete smireni.\n\n• Slušajte svoje telo – Prepoznajte znakove umora i pravite pauze kada je potrebno kako biste sprečili izgaranje."}]$tx$
where key = 'transit.saturn.sextile.natal.mars' and version = 'long';

update public.transit_texts set
  title    = $tx$Stabilizacija snova i duhovnog puta$tx$,
  body     = $tx$Ovaj tranzit predstavlja harmoničan spoj praktičnosti (Saturn) i idealizma (Neptun), omogućavajući vam da na stabilan i strukturiran način integrišete snove, intuiciju i duhovnost u svakodnevni život. Za razliku od konjunkcije koja ima snažniji uticaj, sekstil može delovati suptilno i proći neopaženo ako mu ne posvetite pažnju. Ipak, njegova moć leži upravo u tihoj podršci – pruža vam priliku da radite na ličnom razvoju, da osnažite empatiju i da spojite viziju sa realnošću.

Možete primetiti da vas odjednom privlače teme koje su vam ranije bile strane – poezija, duhovnost, psihologija, umetnost. Ljudi u vašem okruženju, posebno oni osetljiviji i intuitivniji, mogu zapaziti promene u vašem ponašanju čak i pre nego što ih vi sami osvestite. Ovo je idealan period za rad na sebi kroz tišinu, introspekciju i kreativne prakse koje zahtevaju i strukturu i inspiraciju. Umetnici i kreativci mogu doživeti proboj u razvoju svog izraza, dok oni koji su inače više racionalni mogu razviti dublje razumevanje nesvesnog i emocionalnog sloja postojanja.$tx$,
  sections = $tx$[{"heading": "Dugoročni efekti", "body": "Tranzit Saturna sekstil Neptun donosi dugotrajan proces spajanja unutrašnjeg duhovnog sveta sa spoljašnjom stvarnošću. Naučićete kako da gradite na svojim idealima, ali bez bežanja od stvarnog života. Ovaj aspekt vas postepeno vodi ka zrelijem razumevanju sopstvenih snova, bez iluzija i obmana. Postajete sposobni da svoja nadahnuća pretočite u konkretne planove, a duhovni uvidi mogu postati osnov za stabilnije životne odluke.\n\nU dugoročnom smislu, ovaj tranzit vas podučava važnosti balansiranja mašte i strukture – stvarajući temelje za autentičan i održiv lični razvoj. Takođe, mnogi pod ovim aspektom pronalaze duhovne učitelje, započinju terapeutski rad ili razvijaju emocionalnu stabilnost uz pomoć intuicije i discipline."}, {"heading": "Specifične sfere života", "body": "Duhovnost i introspekcija: Pojačano interesovanje za meditaciju, molitvu, simboliku snova ili mistične prakse.\n\nKreativni izražaj: Početak stvaranja umetnosti sa dubljom porukom, ili vraćanje starim, zapostavljenim talentima.\n\nPsihološki uvidi: Bolje razumevanje sopstvenih emocija i podsvesti, kao i veća empatija prema drugima.\n\nProfesionalni razvoj: Mogućnost uključivanja duhovnih vrednosti u karijeru ili stabilizacije umetničkih i humanitarnih poslova.\n\nUnutrašnji mir: Razvijate sposobnost da ostanete sabrani i povezani sa sobom i u teškim situacijama."}, {"heading": "Opšte preporuke", "body": "Spojite intuiciju sa praksomNe ignorišite unutrašnji glas – pretvorite ga u konkretne korak. Mala duhovna rutina može postati kamen-temeljac vaše stabilnosti.\n\nRadite na duhovnoj discipliniRedovna rutina u duhovnim praksama može vam doneti veliku stabilnost. Uspostavljanje strukture u duhovnim navikama donosi dublji fokus i unutrašnji mir.\n\nPišite, stvarajte, vizualizujteKoristite umetničke forme da izrazite svoje unutrašnje procese. Zabeležene ideje mogu kasnije poslužiti kao osnova za ozbiljan projekat.\n\nIzbegavajte beg u iluzijePraktikujte prizemljene metode introspektivnog rada i ne idealizujte ljude ili situacije. Odvajanje mašte od realnosti ključno je za jasnoću i emocionalnu sigurnost.\n\nNegujte tišinu i usporavanjeUsporeni ritam vam sada može pomoći da čujete ono što inače propuštate. Odmor od svakodnevne buke omogućava dublju emocionalnu obradu."}, {"heading": "Pozitivni efekti", "body": "Kreativna realizacijaIdeje i nadahnuća sada mogu dobiti praktičan izraz i trajnu formu. To vam omogućava da stvorite nešto dugotrajno, bazirano na autentičnosti.\n\nStabilna duhovna praksaUspostavljanje redovne i utemeljene duhovne rutine donosi mir i dublji smisao. Osećate sigurnost u sopstvenom unutrašnjem vodstvu i veru u tok života.\n\nProdubljivanje empatijeSaosećanje prema sebi i drugima raste na autentičan način. To vodi ka skladnijim odnosima i boljoj emocionalnoj povezanosti.\n\nBalans snova i stvarnostiUspevate da držite svoje ideale čvrsto na zemlji bez gubitka njihove lepote. Na taj način postajete uzor drugima u ostvarivanju vizija na praktičan način.\n\nUnutrašnja jasnoćaOsećate da znate šta vam je važno i kako to ostvariti bez haotičnih emocija. Jasna mentalna slika vaših ciljeva olakšava odlučivanje i kretanje napred."}, {"heading": "Izazovi", "body": "Nedovoljno opažanje tranzitaMože vam “promaći” ukoliko ste previše u fizičkom svetu i ne pratite unutrašnje promene. To može dovesti do propuštenih prilika za rast i unutrašnji razvoj.\n\nPasivnostIako je aspekt pozitivan, ako ga ne iskoristite svesno – proći će bez rezultata. Ne dozvolite da vreme prođe a da ništa konkretno ne integrišete.\n\nIdealizovanje duhovnostiPostoji rizik da zamenite duhovni razvoj sa fantazijom ili bekstvom. Bitno je razlikovati istinsku duhovnu praksu od emocionalnog bega.\n\nSumnja u intuicijuMožete osećati nelagodu kada treba da slušate unutrašnji glas koji protivreči logici. Vežbanje poverenja u unutrašnje vodstvo donosi dugoročnu sigurnost.\n\nOslanjanje na drugeU želji za razumevanjem možete se previše osloniti na nečije tuđe duhovne smernice. Važno je da ostanete autentični u sopstvenoj potrazi za istinom."}, {"heading": "Saveti", "body": "Uvedite red u svoju kreativnost i duhovnostRasporedi i planovi mogu pomoći da ostanete dosledni sebi. To povećava verovatnoću dugoročnog uspeha i unutrašnjeg ispunjenja.\n\nZapišite svoje snove i unutrašnje uvideMogu sadržati ključne poruke koje vam pomažu da donesete mudre odluke. Vođenje dnevnika snova i meditacija može biti dragocen alat.\n\nPronađite ravnotežu između akcije i kontemplacijeIako vam je introspekcija važna, nemojte zapostaviti spoljašnje aktivnosti. Duhovni uvidi imaju smisla tek kada se primene u stvarnom svetu.\n\nBudite nežni prema sebiNe forsirajte napredak, ovaj tranzit radi “iz senke”, i dozvoljava promene u tišini. Prihvatite spor tempo kao prirodan deo unutrašnje transformacije.\n\nUčite iz snova, ali živite u stvarnostiIskoristite simboliku i vizije, ali ih pretočite u stvarne, male korake. Praktična realizacija duhovnih uvida gradi poverenje u sopstveni put."}]$tx$
where key = 'transit.saturn.sextile.natal.neptune' and version = 'long';

update public.transit_texts set
  title    = $tx$Snaga transformacije kroz viziju budućnosti$tx$,
  body     = $tx$Ovaj tranzit donosi snažan podsticaj za ličnu i kolektivnu transformaciju. Uran u sekstilu sa Plutonom kombinuje intelektualnu probojnost, želju za slobodom i revolucionarnim promenama sa dubokom psihološkom regeneracijom. Ovo je moćan trenutak za oslobađanje od starih obrazaca, sistema i uverenja, i za stvaranje temelja za trajnije promene.

Imate potrebu da prekinete sa onim što više ne funkcioniše i da se otvorite prema nečemu sasvim novom, a često i radikalno drugačijem. Vaša unutrašnja snaga, volja i spremnost da se borite za višu svrhu, sada dolaze do izražaja.$tx$,
  sections = $tx$[{"heading": "Dugoročni efekti", "body": "Ovaj aspekt deluje kao okidač za trajne unutrašnje promene, koje se mogu ticati stavova, vrednosti, profesionalnih ciljeva, pa čak i duhovne orijentacije. Dugoročno, otvaraju se vrata za dublju samospoznaju i proboj kroz ograničenja, posebno ako radite na ličnim ili kolektivnim ciljevima koji zahtevaju viziju, upornost i inovaciju."}, {"heading": "Specifične sfere života", "body": "• Lični razvoj: Snažna želja za promenom identiteta, stava i životnih pravaca.• Psihologija i introspekcija: Pojačano interesovanje za duboke teme – trauma, regeneracija, senke.• Poslovanje i timski rad: Lakše dolazite do rešenja u prethodno zablokiranim profesionalnim situacijama.• Kolektivne promene: Aktivniji ste u reformama, društvenim pokretima ili alternativnim projektima.• Vizija i strategija: Vaša sposobnost da sagledate dublje uzroke i posledice se povećava."}, {"heading": "Opšte preporuke", "body": "• Iskoristite ovaj period za planiranje velikih transformacija.• Otvoreno razgovarajte o tabu temama sa ljudima kojima verujete.• Radite na ličnom osnaživanju kroz introspektivne prakse.• Pratite znakove i obrasce koji ukazuju na unutrašnju potrebu za promenom.• Ne bojte se da zatvorite neka poglavlja – vreme je za evoluciju."}, {"heading": "Pozitivni efekti", "body": "Jasna unutrašnja snaga, donosi Vam hrabrost da pokrenete dublje promene.\n\nVeća psihološka oštrina, pomaže u razumevanju sopstvenih i tuđih motiva.\n\nProdor kroz prepreke, omogućava napredak tamo gde je ranije bilo zastoja.\n\nSklad intuicije i logike, donosi konstruktivne i promišljene odluke.\n\nPojačan uticaj na okolinu, lakše pokrećete druge i inspirišete ih na promene."}, {"heading": "Izazovi", "body": "Sklonost impulsivnim rezovima, može izazvati posledice koje niste planirali.\n\nPreterano oslanjanje na sebe, otežava saradnju i izaziva nerazumevanje.\n\nIntenzivne emocionalne reakcije, mogu Vas udaljiti od stabilnosti.\n\nTeškoće u prihvatanju različitosti, naročito ako drugi ne prate Vašu transformaciju.\n\nMoguć osećaj usamljenosti, dok prolazite kroz duboke unutrašnje promene."}, {"heading": "Saveti", "body": "Usmerite svoju snagu, promene su korisne kada ih kanališete svesno.\n\nPrihvatite procese transformacije, čak i ako deluju zastrašujuće u početku.\n\nSlušajte intuiciju, ali proverite činjenice, idealan je trenutak za balans.\n\nNe donosite odluke naglo, dajte sebi vreme da sagledate širu sliku.\n\nPodelite ideje s drugima, podrška i razgovor mogu otvoriti nova vrata."}]$tx$
where key = 'transit.uranus.sextile.natal.pluto' and version = 'long';

update public.transit_texts set
  title    = $tx$Novi sjaj vaše unutrašnje svetlosti$tx$,
  body     = $tx$Pozitivni susreti Urana i Sunca donose trenutke kada se stara senka sa vašeg bića skida, otvarajući prostor za nepredvidive promene i uzbudljive nove početke. U ovom periodu, vi kao da se budite iz sna zastarelih obrazaca i dobijate priliku da zablistate u svom punom potencijalu. Vaša unutrašnja svetlost dobija dodatni impuls, a život počinje da se čini šarenijim i dinamičnijim.

Osećaj slobode koji vas prati podstiče vas da napustite ustaljene šablone i da eksperimentišete sa novim idejama, kreativnim izrazima i interesovanjima. Sada imate hrabrost da se prikažete onakvi kakvi stvarno jeste, oslobođeni očekivanja drugih. Ovaj tranzit vas poziva da sledite svoje instinkte i razvijate sopstvenu autentičnost.

Vaša energija raste, i sa njom i ambicije koje su vođene željom da ostvarite životni smisao na svoj jedinstven način. Osećate se spremno da napravite skok ka nepoznatom, sa poverenjem da će vas taj put voditi ka ličnoj realizaciji i novim uspesima.$tx$,
  sections = $tx$[{"heading": "Dugoročni efekti", "body": "Ovaj tranzit ostavlja dubok pečat u vašem samopouzdanju i unutrašnjoj snazi. Naučićete kako da efikasno balansirate između spontanosti i strukture, što će vam pomoći da u budućnosti prigrlite promene sa manje straha. Vaš pogled na sebe i svet oko vas biće obogaćen novim perspektivama, što će uticati na donošenje odluka i važne životne izbore.\n\nVaša sposobnost da se prilagodite neočekivanim situacijama i istovremeno ostanete verni sebi predstavlja trajnu unutrašnju promenjivu vrednost. Osećaj slobode koji sada doživljavate postaće temelj za dalji lični i profesionalni razvoj."}, {"heading": "Specifične sfere života", "body": "Kreativnost: dobijate novu inspiraciju i slobodu da eksperimentišete bez straha od osude.\n\nLični razvoj: razvijate jači identitet i spremnost da sledite svoje unutrašnje impulse.\n\nZdravlje: osećate pojačanu energiju i vitalnost, što doprinosi vašem opštem blagostanju.\n\nAmbicije: jasno vam je šta želite, a mogućnosti za napredak se povećavaju.\n\nOdnosi: vaša autentičnost privlači nove ljude i produbljuje postojeće veze."}, {"heading": "Opšte preporuke", "body": "Prihvatite promene koje vam život donosi, jer su one prilika za rast.\n\nIstražujte nove interese bez straha od neuspeha ili osude.\n\nNegujte svoju kreativnost kao izvor unutrašnje snage.\n\nOsluškujte svoju energiju i usmeravajte je ka konstruktivnim ciljevima.\n\nBudite spremni da budete drugačiji i cenite svoju jedinstvenost."}, {"heading": "Pozitivni efekti", "body": "Povećava se vaša kreativna energija i želja za novim iskustvima.\n\nDobijate hrabrost da se izrazite autentično, bez straha od reakcija okoline.\n\nVaša vitalnost raste, pa je lakše realizovati ambiciozne planove.\n\nOtvaraju se nove mogućnosti za lični i profesionalni razvoj.\n\nPovećava se osećaj životne svrhe, što vas motiviše da idete napred."}, {"heading": "Izazovi", "body": "Može vas poneti impulsivnost, pa je važno zadržati dozu razuma.\n\nNeprijatnost zbog nesporazuma ako drugi ne razumeju vaše promene.\n\nRizik od preopterećenja ako se previše upustite u nove projekte odjednom.\n\nMogući otpor okoline prema vašem drugačijem ponašanju.\n\nPonekad se može javiti nemir zbog težnje za stalnom promenom."}, {"heading": "Saveti", "body": "Planirajte svoje korake i dajte sebi vremena da se prilagodite.\n\nKomunicirajte jasno svoje ideje i motive ljudima oko sebe.\n\nOdržavajte balans između slobode i odgovornosti.\n\nBirajte projekte koji zaista rezoniraju sa vašom svrhom.\n\nPraktikujte strpljenje u odnosima i prema sebi."}]$tx$
where key = 'transit.uranus.sextile.natal.sun' and version = 'long';

-- Provera: mora vratiti 0 redova.
select key from public.transit_texts where body like '%<w:%' or sections like '%<w:%';
